mapper.sql:

and T1.PORTFOLIO_ID is null



    AND T1.SEC_MANAGE_ACCT_ID = #{secManageAcctId}


    AND T4.FINPROD_MARKET_ID = #{finprodMarketId}


    AND T3.PA_BUSS_TYPE = #{paBizType}


    AND T1.MDATE >= to_date(#{mdateStart}, 'yyyy-MM-dd')


    AND T1.MDATE <= to_date(#{mdateEnd}, 'yyyy-MM-dd')


    AND T1.TRADE_DATE >= to_date(#{tradeDateStart}, 'yyyy-MM-dd')


    AND T1.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')

select.if:
SELECT t1.*, ROUND(100 - SUM(NVL(fcp.prin_amt, 0)), 6) intPrinAmt FROM ( SELECT '${statusValid}' statusValid, t8.CASH_ID cashId, t8.CASH_TYPE CASH_TYPE, SUM(T8.QTY)*100 QTY, t8.SEC_ACCT_ID secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName,
FPD.COLLECT_TYPE collectType,
CASE WHEN SAI.SEC_ACCT_ID IS NULL THEN 1 ELSE 0 END channel, t10.FINPROD_MARKET_ID, t10.FINPROD_NAME finprodMarketName, TO_CHAR(t8.VDATE, 'yyyy-MM-dd') vDate, TO_CHAR(t8.MDATE, 'yyyy-MM-dd') mDate, T10.FINPROD_ID, T10.CCY, ROUND(t8.INT_AMT, 12) unitIntAmt /*单位应计利息*/ , TO_CHAR(T10.VDATE, 'yyyy-MM-dd') vDateWhole /*起息日*/ , TO_CHAR(T10.MDATE, 'yyyy-MM-dd') mDateWhole /*到期日*/ , ROUND(t8.PRIN_AMT, 4) prinAmt /*还本面额/百元*/ , T8.RANGE_YIELD*100 yield /*区间票面利率（%）*/ , TO_CHAR(T8.PAY_DATE, 'yyyy-MM-dd') payDate /*支付日*/ , TO_CHAR(T8.PAY_DATE, 'yyyy-MM-dd') tradeDate /*交易日*/ , ROUND(sum(T8.intAmt), 8) intAmtTheory /*理论应计利息*/ , ROUND(sum(T8.prinAmt), 4) prinAmtTheory /*理论还本金额*/ , T10.TRADE_MARKET, ROUND(sum(t8.fpriceAmt), 4) fpriceAmt /*理论本息总额*/ , '' PA_BUSS_TYPE from (select T1.FINPROD_ID, T1.AMOUNT QTY, listagg(T1.CASH_TYPE, ',') within group ( order by T1.CASH_ID ) CASH_TYPE, listagg(T1.CASH_ID, ',') within group ( order by T1.CASH_ID ) CASH_ID, min(T1.VDATE) VDATE, T1.MDATE, SUM(T1.CASH_AMT * T1.AMOUNT) fpriceAmt, /*理论本息总额*/ sum(case when T1.CASH_TYPE IN (#{CASH_CLASS_TYPE01}, '04') then 0 else T1.PRIN_AMT * T1.AMOUNT end) prinAmt, max(T1.INT_PRIN_AMT) INT_PRIN_AMT, T1.SEC_ACCT_ID, SUM(T1.PRIN_AMT) PRIN_AMT, SUM(T1.INT_AMT) INT_AMT, SUM(T1.int_amt * T1.AMOUNT) intAmt, /*理论利息*/ T1.PAY_DATE, max(t1.RANGE_YIELD) RANGE_YIELD from (SELECT T1.FINPROD_ID, T1.PORTFOLIO_ID, DECODE(T1.HODING_TYPE, '06', T1.AMOUNT*-1, T1.AMOUNT) AMOUNT, T1.INV_AIM, T1.SEC_ACCT_ID, t2.vdate, t2.mdate, t2.cash_amt, t2.prin_amt, t2.INT_PRIN_AMT, t2.int_amt, t2.cash_id, t2.cash_type, t2.pay_date, t2.RANGE_YIELD FROM PTL_SEC_POSITION T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T2.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01} AND t1.CDATE < t2.MDATE LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = T1.PORTFOLIO_ID WHERE T1.AMOUNT > 0 AND T1.HODING_TYPE IN ('03', '05', '06') and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' AND T1.SEC_ACCT_ID = #{secManageAcctId} AND T2.FINPROD_ID = #{finprodId} AND T2.MDATE = to_date(#{mDate}, 'yyyy-MM-dd') and T2.CASH_TYPE IN (#{CASH_CLASS_TYPE01},#{CASH_CLASS_TYPE02},#{CASH_CLASS_TYPE03},#{CASH_CLASS_TYPE04}) and (t2.INT_AMT > 0 or t2.PRIN_AMT > 0) /*不存在生效的交易*/ and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA LEFT JOIN TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID where TDTA.MP_FINPROD_ID IS NULL and TPDA.TRADE_STATUS = #{TRADE_STATUS01} AND TPDA.IS_CANCEL = #{YESNO_N} and T2.MDATE = TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND (TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID OR TPDA.CHL_ID = T1.SEC_ACCT_ID)) /*不存在流程中的当期或之前的交易*/ AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID where TDTA.MP_FINPROD_ID IS NULL and TPDA.TRADE_STATUS = #{TRADE_STATUS01} AND TPDA.IS_CANCEL = #{YESNO_N} and T2.MDATE >= TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND (TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID OR TPDA.CHL_ID = T1.SEC_ACCT_ID))
AND NOT EXISTS ( SELECT 1 FROM PTL_SEC_POSITION tpsp where tpsp.HODING_TYPE = T1.HODING_TYPE and tpsp.PORTFOLIO_ID = T1.PORTFOLIO_ID and tpsp.SEC_ACCT_ID = T1.SEC_ACCT_ID and tpsp.FINPROD_ID = T1.FINPROD_ID and tpsp.CDATE > T1.CDATE and tpsp.CDATE < t2.MDATE )
) T1 group by T1.FINPROD_ID, T1.MDATE,T1.AMOUNT,T1.INV_AIM, T1.PORTFOLIO_ID, T1.SEC_ACCT_ID, T1.PAY_DATE) T8 LEFT JOIN FIN_PRODUCT T10 ON T10.FINPROD_ID = T8.FINPROD_ID
LEFT JOIN STL_SEC_ACCT_INFO SAI ON T8.SEC_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T8.SEC_ACCT_ID = FP.FINPROD_ID
LEFT JOIN FIN_PRODUCT_ADD FPD ON FP.FINPROD_ID=FPD.FINPROD_ID WHERE T10.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01}
and T10.FINPROD_MARKET_ID = #{finprodMarketId}
GROUP BY t8.CASH_ID , t8.CASH_TYPE, t8.SEC_ACCT_ID,SAI.SEC_ACCT_NAME, fp.FINPROD_NAME,SAI.SEC_ACCT_ID, t8.PRIN_AMT, t8.INT_AMT/*还本金额*/, t10.FINPROD_MARKET_ID, t10.FINPROD_NAME , t8.VDATE, t8.MDATE, T10.FINPROD_ID, T10.CCY, T10.VDATE, T10.MDATE, T8.RANGE_YIELD , T8.PAY_DATE , T10.TRADE_MARKET, FPD.COLLECT_TYPE ) T1 LEFT JOIN FIN_CASH_PLAN fcp ON #{FINPROD_TYPE_TGF01} = fcp.FINPROD_TYPE2 AND fcp.MDATE < to_date(T1.MDATE, 'yyyy-MM-dd') AND T1.FINPROD_ID = fcp.FINPROD_ID and fcp.CASH_TYPE IN (#{CASH_CLASS_TYPE02}) and fcp.PRIN_AMT > 0 GROUP BY t1.statusValid, t1. cashId, t1.CASH_TYPE, t1.QTY, t1.secManageAcctId, t1.channel, t1.secAcctName, t1.FINPROD_MARKET_ID, t1.finprodMarketName, t1.vDate, t1.mDate, t1.FINPROD_ID, t1.CCY, t1.unitIntAmt , t1.vDateWhole , t1.mDateWhole , t1.prinAmt , t1.yield , t1.payDate , t1.tradeDate , t1.intAmtTheory , t1.prinAmtTheory , t1.TRADE_MARKET, t1.fpriceAmt , t1.PA_BUSS_TYPE, t1.collectType

            /*检索项目*/
            SELECT
            /*汇总交易.组合代码 组合*/
            TOTAL.PORTFOLIO_ID,
            pp.PORTFOLIO_NAME,
            /*现金流支付规则.支付频率 付息周期*/

            fcpr.PAY_CYCLE CALC_RULE,


            TOTAL.INV_AIM,

            ROUND(TOTAL.SHARE_AMT*100,2) QTY,

            ROUND(PA_TOTAL.THEORY_PRIN,2) prinAmtTheory,
            /*金融产品交易扩展2.还本金额/理论利息 还本金额*/
            ROUND(TOTAL.PRIN_AMT,2) returnAmount,
            /*金融产品交易汇总业务流程表.起息日 计息开始日*/
            to_char(TOTAL.VDATE, 'yyyy-MM-dd') vDate,
            /*金融产品交易汇总业务流程表.到期日 计息结束日*/
            to_char(TOTAL.MDATE, 'yyyy-MM-dd') mDate,
            /*金融产品交易汇总扩展业务流程表.区间票面利率*/
            PA_TOTAL.RATE*100 yield,
            ROUND(PA_TOTAL.THEORY_INT,2) intAmtTheory,

            ROUND(TOTAL.INT_AMT,2) intAmt,
            ROUND(TOTAL.FEE_AMT,2) channelFee

                FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL
                LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL PA_TOTAL ON TOTAL.TOTLE_TRADE_ID = PA_TOTAL.TOTLE_TRADE_ID


                FROM TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL
                LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL PA_TOTAL ON TOTAL.TOTLE_TRADE_ID = PA_TOTAL.TOTLE_TRADE_ID

            LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = TOTAL.PORTFOLIO_ID
            LEFT JOIN FIN_CASH_INFO fci ON TOTAL.FINPROD_ID = fci.FINPROD_ID
            AND fci.CASH_TYPE_1 = #{CASH_TYPE_1_02} AND fci.CASH_TYPE_2 = #{CASH_TYPE_2_C02}
            LEFT JOIN FIN_CASH_PAY_RULE fcpr on fcpr.CASH_ID = fci.CASH_ID and fcpr.EFF_DATE <= TOTAL.MDATE and  not EXISTS (
				select 1 from FIN_CASH_PAY_RULE fcpr_2
				where fcpr_2.EFF_DATE > fcpr.EFF_DATE
				and fcpr.CASH_ID = fcpr_2.CASH_ID
				and fcpr_2.EFF_DATE <= TOTAL.MDATE
			)
            /*检索条件*/
            WHERE

            /*金融产品交易1.金融产品代码 = 传参.金融产品代码*/
            TOTAL.P_TOTLE_TRADE_ID = #{busiCode}

            and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null'

            and TOTAL.PORTFOLIO_ID
